#!/usr/bin/env bash
# Generated by projectsetup. This canonical installer is shared by every preset.
set -euo pipefail

fail() {
  printf 'projectsetup AI installer: %s\n' "$*" >&2
  exit 1
}

# Only core container parents may be repaired. These exact paths cannot be
# host mounts in generated configurations. Never traverse their descendants.
ensure_parent() {
  local path="$1"
  [[ ! -L "$path" ]] || fail "$path is a symlink; repair the container parent directory"
  mkdir -p "$path" 2>/dev/null || sudo mkdir -p "$path"
  if [[ ! -w "$path" || ! -x "$path" ]]; then
    sudo chown --no-dereference "$(id -u):$(id -g)" "$path"
  fi
  [[ -w "$path" && -x "$path" ]] || fail "$path is not writable; repair the container parent directory"
}

ensure_writable() {
  local path="$1" source="${2:-$1}"
  mkdir -p "$path" 2>/dev/null || fail "cannot create $path; repair host source $source for container IDs $(id -u):$(id -g)"
  [[ -w "$path" && -x "$path" ]] || fail "$path is not writable; repair host source $source for container IDs $(id -u):$(id -g)"
  # Vendor libraries and Git pack files can deliberately be read-only. An
  # owner-owned readable file can be chmodded/replaced by this user if needed;
  # do not mutate its mode merely to run a shared installation. Directories
  # still need read/write/search access, and foreign read-only files fail.
  local blocked
  blocked="$(find "$path" -xdev \( -type d \( ! -readable -o ! -writable -o ! -executable \) -o -type f \( ! -readable -o \( ! -writable ! -uid "$(id -u)" \) \) \) -print -quit 2>/dev/null)" ||
    fail "cannot inspect $path; repair host source $source access"
  [[ -z "$blocked" ]] || fail "$blocked lacks required read/write/search or file-owner access; repair host source $source; no ownership was changed"
}

# A no-argument rerun checks the tools selected when this script was generated.
if (( $# == 0 )); then
  set -- claude opencode
fi

latest_claude_binary() {
  find "$HOME/.local/share/claude/versions/" -mindepth 1 -maxdepth 1 -type f -executable \
    -regextype posix-extended -regex '.*/[0-9]+(\.[0-9]+)*' -print 2>/dev/null |
    LC_ALL=C sort -Vr | sed -n '1p' || true
}

# The versions directory is shared with the host, which adds new versions and
# removes old ones. A fixed symlink would pin this container to one version
# and dangle after host cleanup, so the launcher resolves the newest version
# on every call. Claude Code's updater does not replace a launcher that is not
# a symlink into versions/, and still installs updates there.
write_claude_launcher() {
  local staged="$HOME/.local/bin/.claude-projectsetup-$$"
  cat >"$staged" <<'LAUNCHER'
#!/usr/bin/env bash
# Generated by projectsetup. Runs the newest Claude Code version in the
# shared ~/.local/share/claude/versions directory.
set -euo pipefail
versions="$HOME/.local/share/claude/versions"
latest="$(find "$versions/" -mindepth 1 -maxdepth 1 -type f -executable \
  -regextype posix-extended -regex '.*/[0-9]+(\.[0-9]+)*' -printf '%f\n' 2>/dev/null |
  LC_ALL=C sort -Vr | sed -n '1p' || true)"
if [[ -z "$latest" ]]; then
  printf 'claude: no Claude Code version in %s; run .devcontainer/scripts/install-ai-tools.sh claude\n' "$versions" >&2
  exit 127
fi
exec "$versions/$latest" "$@"
LAUNCHER
  chmod 0755 "$staged"
  mv -Tf "$staged" "$HOME/.local/bin/claude"
}

update=false
if [[ "${1:-}" == --update ]]; then
  update=true
  shift
  (( $# > 0 )) || fail "--update requires at least one tool: opencode, claude, codex"
fi
# Reject bad selections before installing or updating any tool.
for tool in "$@"; do
  case "$tool" in
    opencode|claude|codex) ;;
    *) fail "unsupported AI tool: $tool; use [--update] opencode|claude|codex ..." ;;
  esac
done

# Codex uses the official standalone installation in CODEX_HOME. Generated
# containers mount CODEX_HOME at its host path and set CODEX_HOME to it, so the
# installer's absolute links resolve on the host and in every container, and
# both sides can update the same installation.
install_codex() (
  local root="$1" installer
  installer="$(mktemp)" || fail "cannot create temporary Codex installer"
  trap 'rm -f "$installer"' EXIT
  curl -fsSL https://chatgpt.com/codex/install.sh -o "$installer" || fail "download Codex installer failed"
  CODEX_HOME="$root" CODEX_INSTALL_DIR="$HOME/.local/bin" CODEX_NON_INTERACTIVE=1 sh "$installer" ||
    fail "Codex installer failed"
)

# Prints the command inside the selected release, using the same path as the
# installer's visible command link, or nothing when no release is selected.
codex_command() {
  local current="$1/packages/standalone/current"
  [[ -e "$current" || -L "$current" ]] || return 0
  if [[ ! -e "$current/bin/codex" && -e "$current/codex" ]]; then
    printf '%s\n' "$current/codex"
  else
    printf '%s\n' "$current/bin/codex"
  fi
}

# Release directories are named VERSION-TARGET. A host on another platform,
# such as macOS, installs releases this container cannot execute.
codex_foreign_platform() {
  local release
  release="$(readlink "$1/packages/standalone/current" 2>/dev/null)" || return 1
  release="${release%/}"
  release="${release##*/}"
  case "$release" in
    *-"$(uname -m)"-unknown-linux-musl) return 1 ;;
    *-apple-darwin | *-unknown-linux-musl | *-unknown-linux-gnu | *-pc-windows-msvc) return 0 ;;
  esac
  return 1
}

ensure_parent "$HOME/.local"
ensure_parent "$HOME/.local/bin"
ensure_parent "$HOME/.local/state"
ensure_parent "$HOME/.local/share"
ensure_parent "$HOME/.config"
ensure_parent "$HOME/.cache"

for tool in "$@"; do
  case "$tool" in
    opencode)
      ensure_writable "$HOME/.config/opencode" "host ~/.config/opencode"
      ensure_writable "$HOME/.local/share/opencode" "host ~/.local/share/opencode"
      ensure_writable "$HOME/.opencode" "host ~/.opencode"
      ensure_writable "$HOME/.cache/opencode" "host ~/.cache/opencode"
      opencode_binary="$HOME/.opencode/bin/opencode"
      if previous="$("$opencode_binary" --version 2>/dev/null)"; then
        if "$update"; then
          printf 'Updating OpenCode (previous: %s)\n' "$previous"
          "$opencode_binary" upgrade --method curl || fail "OpenCode update failed; retry --update opencode"
        fi
      else
        command -v curl >/dev/null 2>&1 || fail "curl is required to install OpenCode"
        curl -fsSL https://opencode.ai/install | bash || fail "OpenCode installer failed"
      fi
      [[ -x "$HOME/.opencode/bin/opencode" ]] || fail "OpenCode installer did not create ~/.opencode/bin/opencode"
      ln -sfn "$HOME/.opencode/bin/opencode" "$HOME/.local/bin/opencode"
      "$opencode_binary" --version || fail "OpenCode installation is not executable; check host/container platform compatibility"
      ;;
    claude)
      ensure_writable "$HOME/.claude" "host ~/.claude"
      ensure_writable "$HOME/.local/share/claude" "host ~/.local/share/claude"
      export CLAUDE_CONFIG_DIR="$HOME/.claude"
      claude_binary="$(latest_claude_binary)"
      if [[ -z "$claude_binary" ]] || ! "$claude_binary" --version >/dev/null 2>&1; then
        command -v curl >/dev/null 2>&1 || fail "curl is required to install Claude Code"
        curl -fsSL https://claude.ai/install.sh | bash || fail "Claude Code installer failed"
        claude_binary="$(latest_claude_binary)"
      fi
      [[ -n "$claude_binary" ]] || fail "Claude installer did not create a persisted version binary"
      write_claude_launcher
      "$HOME/.local/bin/claude" --version || fail "Claude Code installation is not executable"
      if "$update"; then
        "$HOME/.local/bin/claude" update || fail "Claude Code update failed"
        "$HOME/.local/bin/claude" --version || fail "Updated Claude Code is not executable"
      fi
      ;;
    codex)
      codex_home="${CODEX_HOME:-$HOME/.codex}"
      [[ "$codex_home" == /* ]] || fail "CODEX_HOME must be an absolute path, got $codex_home"
      ensure_writable "$codex_home" "host CODEX_HOME or ~/.codex"
      codex_root="$codex_home"
      if codex_foreign_platform "$codex_home"; then
        # Never replace the host's own release with a Linux build.
        codex_root="$HOME/.local/share/codex-container"
        printf 'Codex: %s/packages/standalone is built for another platform; using container-local %s\n' "$codex_home" "$codex_root"
        mkdir -p "$codex_root" || fail "cannot create $codex_root"
      fi
      codex_binary="$(codex_command "$codex_root")"
      if [[ -n "$codex_binary" ]]; then
        previous="$("$codex_binary" --version 2>/dev/null)" ||
          fail "Codex binary $codex_binary cannot run; host and container must use compatible Linux/CPU architectures. Repair the installation on the host by rerunning the official Codex installer"
        printf 'Codex: %s\n' "$previous"
      fi
      if "$update" || [[ -z "$codex_binary" ]]; then
        install_codex "$codex_root"
        codex_binary="$(codex_command "$codex_root")"
        [[ -n "$codex_binary" ]] || fail "Codex installer did not create $codex_root/packages/standalone/current"
      fi
      ln -s "$codex_binary" "$HOME/.local/bin/.codex-projectsetup-$$"
      mv -Tf "$HOME/.local/bin/.codex-projectsetup-$$" "$HOME/.local/bin/codex"
      "$HOME/.local/bin/codex" --version || fail "Codex installation is not executable; check host/container platform compatibility"
      ;;
    *)
      fail "unsupported AI tool: $tool"
      ;;
  esac
done
